; ===========================================================================
; Mario art, mappings and DPLCs
; ---------------------------------------------------------------------------
; Generated by tools/chr2md.py from smb1-disasm-master/gfx/sprites.chr.
; Rerun that script after changing it; never edit the generated files by hand.
;
; Uncompressed art is DMA'd and a DMA source must not cross a 128KB boundary,
; so the whole art block is kept inside one 128KB bank (bumped to the next
; bank if it would straddle one).
; ===========================================================================

MarioArtBlock_Size = MarioArt_Tiles*3*$20 + tiles_to_bytes(5) + 2*tiles_to_bytes(12) + 2*tiles_to_bytes(24) + tiles_to_bytes(BowserArt_Tiles)

	align	tiles_to_bytes(1)
MarioArtBlock_Try:
	if (MarioArtBlock_Try>>17)<>((MarioArtBlock_Try+MarioArtBlock_Size-1)>>17)
		align	$20000
	endif
MarioArtBlock:
ArtUnc_Mario:		BINCLUDE	"art/uncompressed/Mario.bin"		; normal colours
ArtUnc_Mario_End:
ArtUnc_MarioFire:	BINCLUDE	"art/uncompressed/MarioFire.bin"	; fiery colours, same tile order
ArtUnc_MarioFire_End:
ArtUnc_Luigi:		BINCLUDE	"art/uncompressed/Luigi.bin"		; Luigi's colours, same tile order
ArtUnc_Luigi_End:
ArtUnc_MarioFireball:	BINCLUDE	"art/uncompressed/MarioFireball.bin"	; fireball + explosion
ArtUnc_MarioFireball_End:
ArtUnc_MarioLife:	BINCLUDE	"art/uncompressed/MarioLife.bin"	; HUD life counter: face + "MARIO" (H13)
ArtUnc_MarioLife_End:
ArtUnc_MarioSignpost:	BINCLUDE	"art/uncompressed/MarioSignpost.bin"	; signpost face panel (H16)
ArtUnc_MarioSignpost_End:
ArtUnc_LuigiLife:	BINCLUDE	"art/uncompressed/LuigiLife.bin"	; HUD life counter: face + "LUIGI"
ArtUnc_LuigiLife_End:
ArtUnc_LuigiSignpost:	BINCLUDE	"art/uncompressed/LuigiSignpost.bin"	; signpost face panel
ArtUnc_LuigiSignpost_End:
ArtUnc_Bowser:		BINCLUDE	"art/uncompressed/Bowser.bin"	; WFZ boss: Bowser, flame, hammer, axe
ArtUnc_Bowser_End:
MarioArtBlock_End:

	if (MarioArtBlock>>17)<>((MarioArtBlock_End-1)>>17)
		fatal "Mario art crosses a 128KB boundary; DMA would corrupt it."
	endif
	if MarioArtBlock_End-MarioArtBlock<>MarioArtBlock_Size
		fatal "MarioArtBlock_Size is out of date with the generated art."
	endif
	if ArtUnc_Mario_End-ArtUnc_Mario<>ArtUnc_MarioFire_End-ArtUnc_MarioFire
		fatal "Mario.bin and MarioFire.bin must be the same size (same tile order)."
	endif
	if ArtUnc_Mario_End-ArtUnc_Mario<>ArtUnc_Luigi_End-ArtUnc_Luigi
		fatal "Mario.bin and Luigi.bin must be the same size (same tile order)."
	endif

; Nemesis object art with the Luigi palette slot freed (decompressed, not DMA'd
; from ROM, so it can go anywhere)
	include	"mario/luigi_slot_arts.asm"

MapUnc_Mario:		include	"mappings/sprite/Mario.asm"
MapRUnc_Mario:		include	"mappings/spriteDPLC/Mario.asm"
MapUnc_MarioFireball:	include	"mappings/sprite/MarioFireball.asm"
MapUnc_Bowser:		include	"mappings/sprite/Bowser.asm"
	if BowserArt_Tiles > $59
		fatal "Bowser's art (\{BowserArt_Tiles} tiles) would overwrite the laser walls' tiles ($59+ of the WFZ boss art)."
	endif
	even
